// Pure-JS port of the boltons.iterutils helpers used by the migrated script:
// flatten, chunked, partition, bucketize.
// Value model: PyDict / PyTuple come from ./pyvalues.mjs; Python lists are
// plain JS arrays; strings and all other values are atomic.

import { PyDict, PyTuple } from './pyvalues.mjs';

function flattenInto(src, out) {
  if (typeof src === 'string') {
    out.push(src);
  } else if (Array.isArray(src)) {
    for (const item of src) flattenInto(item, out);
  } else if (src instanceof PyTuple) {
    for (const item of src.items) flattenInto(item, out);
  } else if (src instanceof PyDict) {
    // boltons iterates dicts over their keys (verified against real library).
    for (const key of src.keys()) flattenInto(key, out);
  } else {
    out.push(src);
  }
}

export function flatten(src) {
  const out = [];
  flattenInto(src, out);
  return out;
}

export function chunked(src, size) {
  const out = [];
  for (let i = 0; i < src.length; i += size) {
    out.push(src.slice(i, i + size));
  }
  return out;
}

export function partition(src, keyFn) {
  const truthy = [];
  const falsy = [];
  for (const item of src) {
    if (keyFn(item)) truthy.push(item);
    else falsy.push(item);
  }
  // FIRST array = key-truthy group, SECOND = falsy group (boltons convention).
  return new PyTuple([truthy, falsy]);
}

export function bucketize(src, keyFn) {
  const out = new PyDict();
  for (const item of src) {
    const key = keyFn(item);
    if (out.has(key)) {
      out.get(key).push(item);
    } else {
      out.set(key, [item]);
    }
  }
  return out;
}

