// Minimal stub of PyDict/PyTuple/pyRepr for scratch-testing iterutils ONLY.
export class PyFloat {
  constructor(value) { this.value = value; }
}
export class PyTuple {
  constructor(items) { this.items = items; }
}
function keyId(k) {
  if (k instanceof PyFloat) return 'n:' + k.value;
  if (typeof k === 'boolean') return 'n:' + (k ? 1 : 0);
  if (typeof k === 'number') return 'n:' + k;
  if (typeof k === 'string') return 's:' + k;
  return 'o:' + String(k);
}
export class PyDict {
  constructor(entries) {
    this._map = new Map();
    if (entries) for (const [k, v] of entries) this.set(k, v);
  }
  set(k, v) {
    const id = keyId(k);
    if (this._map.has(id)) this._map.get(id).value = v;
    else this._map.set(id, { key: k, value: v });
  }
  get(k) { const e = this._map.get(keyId(k)); return e ? e.value : undefined; }
  has(k) { return this._map.has(keyId(k)); }
  keys() { return [...this._map.values()].map(e => e.key); }
  values() { return [...this._map.values()].map(e => e.value); }
  items() { return [...this._map.values()].map(e => new PyTuple([e.key, e.value])); }
  get size() { return this._map.size; }
}
export function pyRepr(v) {
  if (v instanceof PyFloat) return String(v.value);
  if (typeof v === 'number') return String(v);
  if (typeof v === 'boolean') return v ? 'True' : 'False';
  if (v === null || v === undefined) return 'None';
  if (typeof v === 'string') return "'" + v + "'";
  if (Array.isArray(v)) return '[' + v.map(pyRepr).join(', ') + ']';
  if (v instanceof PyTuple) {
    if (v.items.length === 0) return '()';
    const inner = v.items.map(pyRepr).join(', ');
    return '(' + inner + (v.items.length === 1 ? ',' : '') + ')';
  }
  if (v instanceof PyDict) {
    const parts = v.items().map(t => pyRepr(t.items[0]) + ': ' + pyRepr(t.items[1]));
    return '{' + parts.join(', ') + '}';
  }
  return String(v);
}

