// Minimal argparse replica for test19: exactly one required option `--a`
// (one string value, help text "Nested dictionary structure") plus auto -h/--help.
// Behaviors verified byte-exact against CPython argparse.

export function parseArgs(argv, prog) {
  const usage = `usage: ${prog} [-h] --a A\n`;
  const helpText =
    usage +
    '\n' +
    'options:\n' +
    '  -h, --help  show this help message and exit\n' +
    '  --a A       Nested dictionary structure\n';

  const fail = (msg) => {
    process.stderr.write(usage + prog + ': error: ' + msg + '\n');
    process.exit(2);
  };

  let a;
  const extras = [];

  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === '-h' || arg === '--help') {
      process.stdout.write(helpText);
      process.exit(0);
    } else if (arg === '--a') {
      if (i + 1 >= argv.length) {
        fail('argument --a: expected one argument');
      }
      a = argv[++i];
    } else if (arg.startsWith('--a=')) {
      a = arg.slice('--a='.length);
    } else {
      extras.push(arg);
    }
  }

  // Missing-required error takes precedence over unrecognized-arguments.
  if (a === undefined) {
    fail('the following arguments are required: --a');
  }
  if (extras.length > 0) {
    fail('unrecognized arguments: ' + extras.join(' '));
  }

  return { a };
}

