import { pyEval } from './lib/pyliteral.mjs';
import { pyRepr, pyStr, pyTypeName, isPyInt, isPyFloat, pyNum, pyMod, pyLenStr, PyDict } from './lib/pyvalues.mjs';
import { flatten, chunked, partition, bucketize } from './lib/iterutils.mjs';
import { OMD, FrozenDict, dictFromOMD } from './lib/dictutils.mjs';
import { parseArgs } from './lib/argparse.mjs';
import { basename } from 'node:path';

const prog = basename(process.argv[1] || 'test19.mjs');
const args = parseArgs(process.argv.slice(2), prog);

const nestedDict = pyEval(args.a);

const result1 = flatten(nestedDict.keys());
console.log(pyRepr(result1));
const result2 = flatten(nestedDict.values());
console.log(pyRepr(result2));
const result3 = flatten(nestedDict.items());
console.log(pyRepr(result3));
const result4 = flatten([nestedDict.keys(), nestedDict.values()]);
console.log(pyRepr(result4));

const result5 = chunked(result2, 2);
console.log(pyRepr(result5));
const result6 = chunked(result2, 3);
console.log(pyRepr(result6));
const result7 = chunked(result1, 2);
console.log(pyRepr(result7));
const result8 = chunked(result1, 3);
console.log(pyRepr(result8));

let result9;
let result10;
if (result2.every((x) => isPyInt(x) || isPyFloat(x))) {
  result9 = partition(result2, (x) => pyNum(x) > 0);
  console.log(pyRepr(result9));
  result10 = bucketize(result2, (x) => (isPyInt(x) ? pyMod(pyNum(x), 2) : 0));
  console.log(pyRepr(result10));
} else {
  result9 = partition(result2, (x) => pyLenStr(pyStr(x)) > 1);
  console.log(pyRepr(result9));
  result10 = bucketize(result2, (x) => pyLenStr(pyStr(x)));
  console.log(pyRepr(result10));
}

const result11 = partition(result2, (x) => isPyInt(x));
console.log(pyRepr(result11));
const result12 = bucketize(result2, (x) => pyTypeName(x));
console.log(pyRepr(result12));

const omd1 = new OMD();
console.log(pyRepr(omd1));
const omd2 = new OMD();
console.log(pyRepr(omd2));

result2.slice(0, 5).forEach((item, i) => {
  omd1.add(`key_${i % 3}`, item);
  omd2.add(`item_${i % 2}`, item);
});

const result13 = omd1.keys();
console.log(pyRepr(result13));
const result14 = omd2.keys();
console.log(pyRepr(result14));
const result15 = new FrozenDict(dictFromOMD(omd1));
console.log(pyRepr(result15));
const result16 = new FrozenDict(dictFromOMD(omd2));
console.log(pyRepr(result16));

const lenDict = new PyDict();
for (const pair of result15.items()) {
  lenDict.set(pair.items[0], pyLenStr(pyStr(pair.items[1])));
}
const result17 = new FrozenDict(lenDict);
console.log(pyRepr(result17));

