// Migration of the boltons.dictutils subset used by the original script:
// OrderedMultiDict (OMD), dict(omd) conversion, and FrozenDict.
import { PyDict, PyTuple, pyRepr } from './pyvalues.mjs';

// OrderedMultiDict: stores every added (key, value) pair in insertion
// order; duplicate keys are allowed. keys() yields each unique key once,
// in first-seen order (uniqueness follows Python key equality via PyDict).
export class OMD {
  constructor() {
    this._pairs = [];
  }

  add(k, v) {
    this._pairs.push([k, v]);
  }

  keys() {
    const seen = new PyDict();
    for (const [k] of this._pairs) {
      if (!seen.has(k)) {
        seen.set(k, true);
      }
    }
    return seen.keys();
  }

  __pyRepr__() {
    if (this._pairs.length === 0) {
      return 'OrderedMultiDict([])';
    }
    const parts = this._pairs.map(([k, v]) => pyRepr(new PyTuple([k, v])));
    return 'OrderedMultiDict([' + parts.join(', ') + '])';
  }
}

// Replicates Python dict(omd): replay all pairs in order; duplicate keys
// keep their first-seen position, but the LAST value wins.
export function dictFromOMD(omd) {
  const d = new PyDict();
  for (const [k, v] of omd._pairs) {
    d.set(k, v);
  }
  return d;
}

// FrozenDict: immutable snapshot of a PyDict taken at construction time.
// Insertion (key) order is preserved.
export class FrozenDict {
  constructor(pyDict) {
    this._entries = pyDict.items().map((t) => [t.items[0], t.items[1]]);
  }

  keys() {
    return this._entries.map(([k]) => k);
  }

  values() {
    return this._entries.map(([, v]) => v);
  }

  items() {
    return this._entries.map(([k, v]) => new PyTuple([k, v]));
  }

  __pyRepr__() {
    return 'FrozenDict(' + pyRepr(new PyDict(this._entries)) + ')';
  }
}

