import { flatten, chunked, partition, bucketize } from './iterutils.mjs';
import { PyDict, PyTuple, PyFloat, pyRepr } from './pyvalues.mjs';

let failures = 0;
function check(name, actual, expected) {
  const ok = actual === expected;
  if (!ok) failures++;
  console.log((ok ? 'PASS' : 'FAIL') + ' ' + name + ' => ' + actual + (ok ? '' : ' (expected ' + expected + ')'));
}

// flatten: nested arrays, tuples, dict (keys only), strings atomic
const d = new PyDict([['c', 3]]);
const items = [
  new PyTuple(['a', [1, 2]]),
  new PyTuple(['b', d]),
  new PyTuple(['d', 4]),
];
check('flatten items', pyRepr(flatten(items)), "['a', 1, 2, 'b', 'c', 'd', 4]");
check('flatten strings atomic', pyRepr(flatten(['hello', ['ab', 'cd']])), "['hello', 'ab', 'cd']");
check('flatten atoms', pyRepr(flatten([1, new PyFloat(2.5), true, null])), '[1, 2.5, True, None]');
check('flatten empty', pyRepr(flatten([])), '[]');

// chunked
check('chunked size 2', pyRepr(chunked([1, -2, new PyFloat(3.5)], 2)), '[[1, -2], [3.5]]');
check('chunked size 3', pyRepr(chunked([1, -2, 3, 4], 3)), '[[1, -2, 3], [4]]');
check('chunked empty', pyRepr(chunked([], 2)), '[]');

// partition: numeric
const p1 = partition([1, -2, new PyFloat(3.5)], x => (x instanceof PyFloat ? x.value : x) > 0);
check('partition numeric', pyRepr(p1), '([1, 3.5], [-2])');
// partition: strings with int key -> all falsy
const p2 = partition(['a', 'bb'], x => typeof x === 'number');
check('partition strings', pyRepr(p2), "([], ['a', 'bb'])");
// order preserved
const p3 = partition([3, 1, 4, 1, 5, 9, 2, 6], x => x % 2 === 0);
check('partition order', pyRepr(p3), '([4, 2, 6], [3, 1, 1, 5, 9])');

// bucketize: verified example {0: [10, 2.5, -8, 4], 1: [-3, 7]}
const vals = [10, -3, 7, new PyFloat(2.5), -8, 4];
const b1 = bucketize(vals, x => (typeof x === 'number' || x instanceof PyFloat)
  ? ((x instanceof PyFloat ? 0 : ((x % 2) + 2) % 2))
  : 0);
// key fn: x % 2 if isinstance int else 0 ; -3 % 2 == 1 in Python
check('bucketize verified', pyRepr(b1), '{0: [10, 2.5, -8, 4], 1: [-3, 7]}');
// first-seen key order
const b2 = bucketize(['a', 'bb', 'c', 'dd'], s => s.length);
check('bucketize order', pyRepr(b2), "{1: ['a', 'c'], 2: ['bb', 'dd']}");
// values are plain JS arrays
console.log((Array.isArray(b1.get(0)) ? 'PASS' : 'FAIL') + ' bucketize values are JS arrays');
if (!Array.isArray(b1.get(0))) failures++;
// partition returns PyTuple of plain JS arrays
console.log(((p1 instanceof PyTuple && Array.isArray(p1.items[0]) && Array.isArray(p1.items[1])) ? 'PASS' : 'FAIL') + ' partition returns PyTuple of JS arrays');
if (!(p1 instanceof PyTuple)) failures++;

process.exit(failures ? 1 : 0);

