import { OMD, dictFromOMD, FrozenDict } from './dictutils.mjs';
import { PyDict, PyTuple, PyFloat, pyRepr } from './pyvalues.mjs';

let failures = 0;
function eq(actual, expected, label) {
  if (actual !== expected) {
    failures++;
    console.log(`FAIL ${label}: got ${actual}, want ${expected}`);
  } else {
    console.log(`ok   ${label}`);
  }
}

// Empty OMD repr
const omd0 = new OMD();
eq(pyRepr(omd0), 'OrderedMultiDict([])', 'empty OMD repr');
eq(JSON.stringify(omd0.keys()), '[]', 'empty OMD keys');

// Verified scenario from the contract:
// adds (key_0,10),(key_1,-3),(key_2,7),(key_0,2.5),(key_1,-8)
const omd = new OMD();
omd.add('key_0', 10);
omd.add('key_1', -3);
omd.add('key_2', 7);
omd.add('key_0', new PyFloat(2.5));
omd.add('key_1', -8);

eq(JSON.stringify(omd.keys()), '["key_0","key_1","key_2"]', 'OMD keys unique first-seen');
eq(pyRepr(omd), "OrderedMultiDict([('key_0', 10), ('key_1', -3), ('key_2', 7), ('key_0', 2.5), ('key_1', -8)])", 'OMD repr');

// dictFromOMD: last value wins, first-seen position
const d = dictFromOMD(omd);
eq(pyRepr(d), "{'key_0': 2.5, 'key_1': -8, 'key_2': 7}", 'dictFromOMD');

// FrozenDict
const fd = new FrozenDict(d);
eq(pyRepr(fd), "FrozenDict({'key_0': 2.5, 'key_1': -8, 'key_2': 7})", 'FrozenDict repr');
eq(JSON.stringify(fd.keys()), '["key_0","key_1","key_2"]', 'FrozenDict keys');
eq(pyRepr(fd.items()), "[('key_0', 2.5), ('key_1', -8), ('key_2', 7)]", 'FrozenDict items are PyTuples');
eq(fd.items()[0] instanceof PyTuple, true, 'FrozenDict items element type');

// Empty FrozenDict
eq(pyRepr(new FrozenDict(new PyDict())), 'FrozenDict({})', 'empty FrozenDict repr');

// Snapshot semantics: mutating source dict after construction must not affect FrozenDict
d.set('key_0', 999);
d.set('extra', 1);
eq(pyRepr(fd), "FrozenDict({'key_0': 2.5, 'key_1': -8, 'key_2': 7})", 'FrozenDict is a snapshot');

// Result17-style: FrozenDict built from another FrozenDict's items
const d17 = new PyDict(fd.items().map((t) => [t.items[0], String(t.items[1]).length]));
const fd17 = new FrozenDict(d17);
eq(pyRepr(fd17), "FrozenDict({'key_0': 3, 'key_1': 2, 'key_2': 1})", 'FrozenDict comprehension-style build');

// Single-pair OMD repr (tuple repr inside list, no trailing comma in list)
const omd1 = new OMD();
omd1.add('a', 1);
eq(pyRepr(omd1), "OrderedMultiDict([('a', 1)])", 'single-pair OMD repr');

process.exit(failures ? 1 : 0);

