      out = digits + '0'.repeat(P + 1 - digits.length) + '.0';
    }
  } else {
    out = '0.' + '0'.repeat(-P - 1) + digits;
  }
  return sign + out;
}

function pyStrRepr(s) {
  // Default quote is '; use " only if the string has ' but not ".
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    const code = ch.codePointAt(0);
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (code < 0x20 || (code >= 0x7f && code <= 0xa0)) {
      out += '\\x' + code.toString(16).padStart(2, '0');
    } else {
      out += ch;
    }
  }
  return out + quote;
}

export function pyRepr(v) {
  if (v instanceof PyFloat) return pyFloatRepr(v.value);
  if (typeof v === 'boolean') return v ? 'True' : 'False';
  if (typeof v === 'number') return String(v);
  if (v === null || v === undefined) return 'None';
  if (typeof v === 'string') return pyStrRepr(v);
  if (Array.isArray(v)) return '[' + v.map(pyRepr).join(', ') + ']';
  if (v instanceof PyTuple) {
    if (v.items.length === 0) return '()';
    if (v.items.length === 1) return '(' + pyRepr(v.items[0]) + ',)';
    return '(' + v.items.map(pyRepr).join(', ') + ')';
  }
  if (v instanceof PyDict) {
    if (v.size === 0) return '{}';
    const parts = [];
    for (const item of v.items()) {
      parts.push(pyRepr(item.items[0]) + ': ' + pyRepr(item.items[1]));
    }
    return '{' + parts.join(', ') + '}';
  }
  if (typeof v.__pyRepr__ === 'function') return v.__pyRepr__();
  return String(v);
}

// Python str(): like repr, except a bare string returns itself unquoted.
export function pyStr(v) {
  if (typeof v === 'string') return v;
  return pyRepr(v);
}

export function pyTypeName(v) {
  if (typeof v === 'boolean') return 'bool';
  if (typeof v === 'number') return 'int';
  if (v instanceof PyFloat) return 'float';
  if (typeof v === 'string') return 'str';
  if (v === null || v === undefined) return 'NoneType';
  if (Array.isArray(v)) return 'list';
  if (v instanceof PyTuple) return 'tuple';
  if (v instanceof PyDict) return 'dict';
  return typeof v;
}

// Python isinstance(x, int): bool IS int.
export function isPyInt(v) {
  return typeof v === 'boolean' || typeof v === 'number';
}

export function isPyFloat(v) {
  return v instanceof PyFloat;
}

export function pyNum(v) {
  if (v instanceof PyFloat) return v.value;
  if (typeof v === 'boolean') return v ? 1 : 0;
  return v;
}

// Python %: result takes the sign of b.
export function pyMod(a, b) {
  const r = ((a % b) + b) % b;
  // Avoid -0 for negative b with exact division; Python gives 0 there too
  // for ints, but normalize so integer inputs yield a plain integer result.
  return Object.is(r, -0) ? 0 : r;
}

// Python len(str): Unicode code points.
export function pyLenStr(s) {
  return [...s].length;
}

