// pyliteral.mjs — parser for the Python literal subset accepted by eval:
// None, True/False, ints, floats, strings (with Python escapes), lists,
// tuples, and dicts, with arbitrary nesting and whitespace.
// Values are returned in the pyvalues model: floats as PyFloat, tuples as
// PyTuple, dicts as PyDict, ints as JS numbers, strings as JS strings.

import { PyFloat, PyTuple, PyDict } from './pyvalues.mjs';

class Parser {
  constructor(src) {
    this.src = src;
    this.pos = 0;
  }

  error(msg) {
    throw new Error(`invalid literal at position ${this.pos}: ${msg}`);
  }

  skipWs() {
    while (this.pos < this.src.length && /[ \t\n\r\f\v]/.test(this.src[this.pos])) {
      this.pos++;
    }
  }

  peek() {
    return this.src[this.pos];
  }

  parse() {
    this.skipWs();
    const v = this.parseValue();
    this.skipWs();
    if (this.pos !== this.src.length) this.error('unexpected trailing input');
    return v;
  }

  parseValue() {
    this.skipWs();
    const ch = this.peek();
    if (ch === undefined) this.error('unexpected end of input');
    if (ch === '[') return this.parseList();
    if (ch === '(') return this.parseTupleOrGroup();
    if (ch === '{') return this.parseDict();
    if (ch === "'" || ch === '"') return this.parseString();
    if (ch === '-' || ch === '+' || (ch >= '0' && ch <= '9') || ch === '.') {
      return this.parseNumber();
    }
    if (/[A-Za-z_]/.test(ch)) return this.parseName();
    this.error(`unexpected character ${JSON.stringify(ch)}`);
  }

  parseName() {
    const rest = this.src.slice(this.pos);
    if (rest.startsWith('None')) {
      this.pos += 4;
      return null;
    }
    if (rest.startsWith('True')) {
      this.pos += 4;
      return true;
    }
    if (rest.startsWith('False')) {
      this.pos += 5;
      return false;
    }
    this.error('unknown name');
  }

  parseList() {
    this.pos++; // consume '['
    const items = [];
    this.skipWs();
    if (this.peek() === ']') {
      this.pos++;
      return items;
    }
    for (;;) {
      items.push(this.parseValue());
      this.skipWs();
      const ch = this.peek();
      if (ch === ',') {
        this.pos++;
        this.skipWs();
        if (this.peek() === ']') {
          this.pos++;
          return items; // trailing comma
        }
        continue;
      }
      if (ch === ']') {
        this.pos++;
        return items;
      }
      this.error('expected "," or "]" in list');
    }
  }

  parseTupleOrGroup() {
    this.pos++; // consume '('
    this.skipWs();
    if (this.peek() === ')') {
      this.pos++;
      return new PyTuple([]);
    }
    const first = this.parseValue();
    this.skipWs();
    const ch = this.peek();
    if (ch === ')') {
      // Bare parenthesized value with no comma is just grouping.
      this.pos++;
      return first;
    }
    if (ch !== ',') this.error('expected "," or ")" after element');
    const items = [first];
    while (this.peek() === ',') {
      this.pos++;
      this.skipWs();
      if (this.peek() === ')') {
        this.pos++;
        return new PyTuple(items); // trailing comma, e.g. (1,)
      }
      items.push(this.parseValue());
      this.skipWs();
    }
    if (this.peek() !== ')') this.error('expected ")" to close tuple');
    this.pos++;
    return new PyTuple(items);
  }

  parseDict() {
    this.pos++; // consume '{'
    const d = new PyDict();
    this.skipWs();
    if (this.peek() === '}') {
      this.pos++;
      return d;
    }
    for (;;) {
      const k = this.parseValue();
      this.skipWs();
      if (this.peek() !== ':') this.error('expected ":" in dict');
      this.pos++;
      const v = this.parseValue();
      d.set(k, v);
      this.skipWs();
      const ch = this.peek();
      if (ch === ',') {
        this.pos++;
        this.skipWs();
        if (this.peek() === '}') {
          this.pos++;
          return d; // trailing comma
        }
        continue;
      }
      if (ch === '}') {
        this.pos++;
        return d;
      }
      this.error('expected "," or "}" in dict');
    }
  }

  parseString() {
    const quote = this.src[this.pos];
    this.pos++;
    let out = '';
    for (;;) {
      if (this.pos >= this.src.length) this.error('unterminated string');
      const ch = this.src[this.pos];
      if (ch === quote) {
        this.pos++;
        return out;
      }
      if (ch === '\\') {
        this.pos++;
        if (this.pos >= this.src.length) this.error('unterminated escape');
        const e = this.src[this.pos];
        this.pos++;
        switch (e) {
          case '\\': out += '\\'; break;
          case "'": out += "'"; break;
          case '"': out += '"'; break;
          case 'n': out += '\n'; break;
          case 't': out += '\t'; break;
          case 'r': out += '\r'; break;
          case 'a': out += ''; break;
          case 'b': out += '\b'; break;
          case 'f': out += ' '; break;
          case 'v': out += ''; break;
          case '0': out += '\0'; break;
          case 'x': {
            const hex = this.src.substr(this.pos, 2);
            if (!/^[0-9a-fA-F]{2}$/.test(hex)) this.error('bad \\x escape');
            out += String.fromCodePoint(parseInt(hex, 16));
            this.pos += 2;
            break;
          }
          case 'u': {
            const hex = this.src.substr(this.pos, 4);
            if (!/^[0-9a-fA-F]{4}$/.test(hex)) this.error('bad \\u escape');
            out += String.fromCodePoint(parseInt(hex, 16));
            this.pos += 4;
            break;
          }
          case 'U': {
            const hex = this.src.substr(this.pos, 8);
            if (!/^[0-9a-fA-F]{8}$/.test(hex)) this.error('bad \\U escape');
            out += String.fromCodePoint(parseInt(hex, 16));
            this.pos += 8;
            break;
          }
          default:
            // Unknown escapes: Python keeps the backslash (e.g. "\q").
            out += '\\' + e;
        }
        continue;
      }
      out += ch;
      this.pos++;
    }
  }

  parseNumber() {
    const rest = this.src.slice(this.pos);
    // Int part may be empty for forms like .5; exponent is digits[.digits][eE...]
    const m = /^[+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?/.exec(rest);
    if (!m) this.error('invalid number');
    const tok = m[0];
    this.pos += tok.length;
    if (/[.eE]/.test(tok)) return new PyFloat(parseFloat(tok));
    return parseInt(tok, 10);
  }
}

export function pyEval(src) {
  if (typeof src !== 'string') throw new Error('pyEval expects a string');
  return new Parser(src).parse();
}

